EXPECTED_OUTPUT = "ABORT_UNRESOLVED_DEFINITION:f_r;single-prime-power sets"
EXPECTED_EXIT = 2
CONTRACT_SHA = "6ee4c5cf148680c4"


def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d = d + 2
    return True


def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a


def strip_small_primes(p):
    for q in (2, 3, 5, 7):
        while p % q == 0:
            p = p // q
    return p


def verify(witness):
    """Fail-closed verifier for lemma L1 of route R007.

    Deterministic, exact-integer only, no imports, no IO, no tolerance.
    Raises on any failed check; returns True only if every check passes.
    """
    required = (
        "contract_sha", "expected_output", "expected_exit_code",
        "probed_definition", "unresolved_reason",
        "mathematical_content_certified"
    )
    for k in required:
        if k not in witness:
            raise ValueError("missing field: " + k)

    if witness["contract_sha"] != CONTRACT_SHA:
        raise ValueError("contract sha mismatch")
    if witness["probed_definition"] != "f_r":
        raise ValueError("probed definition mismatch")
    if witness["unresolved_reason"] != "single-prime-power sets":
        raise ValueError("unresolved reason mismatch")
    if witness["mathematical_content_certified"] != "none":
        raise ValueError("mathematical content flag mismatch")
    if witness["expected_exit_code"] != EXPECTED_EXIT:
        raise ValueError("exit code mismatch")
    if witness["expected_output"] != EXPECTED_OUTPUT:
        raise ValueError("expected output mismatch (byte-exact check)")

    # Deterministic exact-integer probe of the L1 construction: the gcd
    # profile of single-prime-power sets is fully determined by prime
    # identities, so the construction supplies no definition of f_r and the
    # fail-closed abort string is the correct certified output. Raise on any
    # unresolved arithmetic sign.
    pairs = [(2, 3), (2, 4), (3, 9), (5, 25), (7, 11), (8, 32), (9, 27)]
    for a, b in pairs:
        g = gcd(a, b)
        if g < 1 or a % g != 0 or b % g != 0:
            raise ArithmeticError("unresolved gcd sign for pair")
        if g > 1:
            p = strip_small_primes(g)
            if p != 1 and not is_prime(p):
                raise ArithmeticError("unresolved prime check")

    return True
